<?php
requireAdmin();$pdo=db();$p=pfx();$user=currentUser();$activePage='blog';$pageTitle='Blog Posts';
if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf()){$a=$_POST['action']??'';$id=(int)($_POST['id']??0);$sl=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$_POST['title']??''),'-'));
if($a==='save'){if($id)$pdo->prepare("UPDATE `{$p}blog_posts` SET title=?,slug=?,content=?,excerpt=?,category=?,tags=?,featured_image=?,meta_title=?,meta_desc=?,status=?,updated_at=NOW() WHERE id=?")->execute([$_POST['title'],$sl,$_POST['content']??'',$_POST['excerpt']??'',$_POST['category']??'',$_POST['tags']??'',$_POST['featured_image']??'',$_POST['meta_title']??'',$_POST['meta_desc']??'',$_POST['status'],$id]);
else $pdo->prepare("INSERT INTO `{$p}blog_posts`(title,slug,content,excerpt,category,tags,featured_image,meta_title,meta_desc,status,author_id,created_at)VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())")->execute([$_POST['title'],$sl,$_POST['content']??'',$_POST['excerpt']??'',$_POST['category']??'',$_POST['tags']??'',$_POST['featured_image']??'',$_POST['meta_title']??'',$_POST['meta_desc']??'',$_POST['status'],$user['id']]);
redirect('/admin/blog');}
if($a==='delete'){$pdo->prepare("DELETE FROM `{$p}blog_posts` WHERE id=?")->execute([$id]);redirect('/admin/blog');}}
try{$posts=$pdo->query("SELECT b.*,u.name AS author FROM `{$p}blog_posts` b LEFT JOIN `{$p}users` u ON u.id=b.author_id ORDER BY b.created_at DESC")->fetchAll();}catch(Exception $e){$posts=[];}
ob_start();?>
<div class="ph"><div><div class="pt">Blog Posts</div></div><button class="btn bp" onclick="document.getElementById('bmid').value=0;document.getElementById('bmform').reset();oM('bmo')">+ New Post</button></div>
<div class="panel"><div class="tw"><table><thead><tr><th>TITLE</th><th>CATEGORY</th><th>AUTHOR</th><th>VIEWS</th><th>STATUS</th><th>DATE</th><th>ACTIONS</th></tr></thead><tbody>
