$js='<script>function editPost(p){document.getElementById("bmtitle").textContent="Edit Post";document.getElementById("bmid").value=p.id;document.getElementById("bm_t").value=p.title||"";document.getElementById("bm_st").value=p.status||"draft";document.getElementById("bm_c").value=p.category||"";document.getElementById("bm_tg").value=p.tags||"";document.getElementById("bm_img").value=p.featured_image||"";document.getElementById("bm_ex").value=p.excerpt||"";document.getElementById("bm_con").value=p.content||"";document.getElementById("bm_mt").value=p.meta_title||"";document.getElementById("bm_md").value=p.meta_desc||"";oM("bmo");}</script>';
